const cands = [], skipped = [];
const hasMargin = rows.some(r => r.margin);
let degraded = false; // 安全边际指标整体未就绪 → 保守：本轮不出推荐
rows.filter(r => r.w > 0 && r.t).forEach(r => {
  r.capPct = Math.min(r.w, maxS);
  if (!r.price) { skipped.push({ r: r, why: '无行情' }); return; }
  // #2 基本面越线（family/foreign 实控，或 OCF/分红连续两年<1）一票否决：不进买入清单
  if (r.fundBreak) {
    skipped.push({ r: r, why: '基本面越线（' + ((r.t && (r.t.governance === 'family' || r.t.governance === 'foreign')) ? '实控人非国资' : 'OCF/分红连续两年<1') + '），不参与买入' });
    return;
  }
  // 硬门槛：有安全边际数据时，必须达股息率目标价（一票否决）；分位/布林带只作加分。
  if (hasMargin && r.margin) {
    if (!r.marginBuy) {
      const why = [];
      if (r.buyToTgtPct != null && r.buyToTgtPct < 0) why.push('距目标价还差 ' + fmt(-r.buyToTgtPct, 1) + '%');
      if (r.margin.yldPct != null) why.push('分位 ' + fmt(r.margin.yldPct, 0));
      skipped.push({ r: r, why: '未达股息率目标价（' + (why.join('，') || '指标未触发') + '）' });
      return;
    }
  } else {
    // #3 降级：安全边际指标未就绪时，不出推荐（保守口径），只提示未就绪
    degraded = true;
    skipped.push({ r: r, why: '安全边际指标未就绪' });
    return;
  }
  if (r.mv >= r.capPct / 100 * base - 1) {
    skipped.push({ r: r, why: r.mv > r.capPct / 100 * base + 1 ? '已超上限' : '已到上限' });
    return;
  }
  cands.push(r);
});
if (degraded) return { items: [], skipped: skipped, spend: 0, left: amount, base: base, feeTotal: 0, feePct: 0, maxBuys: maxBuys, minTicket: minTicket, degraded: true };

